INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (1, N'account', N'How do I create an account?', N'Click Sign Up and choose your role (Guest, Customer, Stallholder). After signing up, you''ll be brought to the correct dashboard.', N'sign up signup register account role guest customer stallholder', 1, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (2, N'account', N'I can''t log in. What should I do?', N'Double-check your email and password. If you forgot your password, use the password recovery option on the login page.', N'login sign in cannot sign in password forgot reset', 2, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (3, N'customers', N'How do I browse stalls and menus?', N'Go to Centres, choose a hawker centre, then select a stall to view its menu, details, and hygiene grade.', N'browse stalls menu centre centres hawker', 3, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (4, N'customers', N'Where can I see my order status?', N'After placing an order, go to your Orders page to view the latest status and details.', N'order status track orders cart checkout', 4, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (5, N'customers', N'How do I leave feedback or a review?', N'After your experience, submit feedback from the feedback/review section. Reviews help stallholders improve and help other customers decide.', N'review feedback rating comment', 5, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (6, N'stallholders', N'How do I manage my stall and menu?', N'Use your Stallholder dashboard to update stall information and menu items. Changes help customers see your latest offerings.', N'manage stall menu items update profile details', 6, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (7, N'stallholders', N'How do I view incoming orders?', N'Go to your dashboard/orders section to see new orders and manage their progress.', N'orders incoming accept prepare complete', 7, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (8, N'nea', N'How do inspections work?', N'Inspections may be scheduled in advance. After an inspection is completed, hygiene results can be recorded and shown for public awareness.', N'inspection schedule nea upcoming completed cancelled', 8, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (9, N'nea', N'What do hygiene grades mean?', N'Hygiene grades help customers make informed decisions. A better grade generally indicates stronger hygiene standards.', N'hygiene grade a b c d excellent good average poor', 9, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (10, N'payments', N'How do payments work?', N'Payments are made during checkout. Always review your order and total amount before confirming.', N'payment pay checkout bill charges', 10, 1)
INSERT [dbo].[Faqs] ([faqId], [category], [question], [answer], [keywords], [sortOrder], [isActive]) VALUES (11, N'support', N'I still need help. Who can I contact?', N'Use Contact Us to send a message. Include your role and a clear description so we can help faster.', N'contact support message help cannot find answer', 11, 1)
SET IDENTITY_INSERT [dbo].[Faqs] OFF
GO
